// async/await: stackless, Promise-based. An await is a microtask hop.
async function handle(id) {
    try {
        const user   = await fetchUser(id);      // straight-line, not nested callbacks
        const orders = await fetchOrders(user);
        return { user, orders };                 // early return and try/catch work across awaits
    } catch (e) {
        if (e.name === 'AbortError') throw e;   // cancellation is a distinct signal
        throw new Error('handle failed', { cause: e });
    }
}

// generators: stackless, consumer-driven. Use when the consumer pulls.
function* treeWalk(node) {
    if (!node) return;
    yield node.value;
    yield* treeWalk(node.left);                 // delegation: one flat chain
    yield* treeWalk(node.right);
}
